package middleware

import (
	"context"
	"net/http"
	"strings"

	"github.com/golang-jwt/jwt/v5"
)

// contextKey 私有类型，防止 key 冲突
type contextKey string

// UserIDKey 上下文中存储 user_id 的 key
const UserIDKey contextKey = "user_id"

// AuthRequired JWT 鉴权中间件
func AuthRequired(secret string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			tokenStr := extractBearer(r)
			if tokenStr == "" {
				writeAuthError(w, "需要登录")
				return
			}

			claims, err := parseJWT(tokenStr, secret)
			if err != nil {
				writeAuthError(w, "token无效")
				return
			}

			userID, ok := claims["user_id"].(float64)
			if !ok {
				writeAuthError(w, "token无效")
				return
			}

			ctx := context.WithValue(r.Context(), UserIDKey, int64(userID))
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}

func extractBearer(r *http.Request) string {
	auth := r.Header.Get("Authorization")
	if !strings.HasPrefix(auth, "Bearer ") {
		return ""
	}
	return strings.TrimPrefix(auth, "Bearer ")
}

func parseJWT(tokenStr, secret string) (jwt.MapClaims, error) {
	token, err := jwt.Parse(tokenStr, func(t *jwt.Token) (interface{}, error) {
		return []byte(secret), nil
	})
	if err != nil || !token.Valid {
		return nil, err
	}
	claims, ok := token.Claims.(jwt.MapClaims)
	if !ok {
		return nil, jwt.ErrSignatureInvalid
	}
	return claims, nil
}

func writeAuthError(w http.ResponseWriter, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusUnauthorized)
	w.Write([]byte(`{"error":"` + msg + `"}`))
}

func writeForbidden(w http.ResponseWriter, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusForbidden)
	w.Write([]byte(`{"error":"` + msg + `"}`))
}

package handler

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"

	"github.com/kiddyt00/yiguan/internal/middleware"
	"github.com/kiddyt00/yiguan/internal/store"
)

type UserHandler struct {
	store    store.Store
	wxAppID  string
	wxSecret string
}

func NewUserHandler(st store.Store) *UserHandler {
	return &UserHandler{store: st}
}

func (h *UserHandler) SetWechatConfig(appID, appSecret string) {
	h.wxAppID = appID
	h.wxSecret = appSecret
}

type updateUserReq struct {
	Nickname string `json:"nickname"`
	Address  string `json:"address"`
}

type bindWechatReq struct {
	Code string `json:"code"`
}

func (h *UserHandler) GetUser(w http.ResponseWriter, r *http.Request) {
	userID := r.Context().Value(middleware.UserIDKey).(int64)
	user, err := h.store.GetUserByID(userID)
	if err != nil {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "用户不存在"})
		return
	}
	fillUserAvatar(user)
	user.Password = ""
	remaining, _ := h.store.GetRemainingQuota(userID)
	writeJSON(w, http.StatusOK, map[string]interface{}{
		"user":            user,
		"remaining_quota": remaining,
	})
}

func (h *UserHandler) UpdateUser(w http.ResponseWriter, r *http.Request) {
	userID := r.Context().Value(middleware.UserIDKey).(int64)
	var req updateUserReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求格式错误"})
		return
	}
	if err := h.store.UpdateUser(userID, req.Nickname, req.Address); err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "更新失败"})
		return
	}
	user, _ := h.store.GetUserByID(userID)
	fillUserAvatar(user)
	user.Password = ""
	remaining, _ := h.store.GetRemainingQuota(userID)
	writeJSON(w, http.StatusOK, map[string]interface{}{
		"user":            user,
		"remaining_quota": remaining,
	})
}

func (h *UserHandler) BindWechat(w http.ResponseWriter, r *http.Request) {
	userID := r.Context().Value(middleware.UserIDKey).(int64)
	var req bindWechatReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.Code == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "缺少 code"})
		return
	}
	if h.wxAppID == "" || h.wxSecret == "" {
		writeJSON(w, http.StatusBadGateway, map[string]string{"error": "微信登录未配置"})
		return
	}
	openid, err := exchangeWechatCode(h.wxAppID, h.wxSecret, req.Code)
	if err != nil {
		log.Printf("微信 code 换 openid 失败: %v", err)
		writeJSON(w, http.StatusBadGateway, map[string]string{"error": "微信登录失败"})
		return
	}
	existing, _ := h.store.GetUserByOpenID(openid)
	if existing != nil && existing.ID != userID {
		writeJSON(w, http.StatusConflict, map[string]string{"error": "该微信已被其他账号绑定"})
		return
	}
	if err := h.store.UpdateUserOpenID(userID, openid); err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "绑定失败"})
		return
	}
	user, _ := h.store.GetUserByID(userID)
	user.Password = ""
	writeJSON(w, http.StatusOK, map[string]interface{}{"user": user, "bound": true, "openid": openid})
}

func exchangeWechatCode(appID, secret, code string) (string, error) {
	if appID == "" || secret == "" {
		return "", fmt.Errorf("微信小程序未配置")
	}
	resp, err := http.Get(fmt.Sprintf("https://api.weixin.qq.com/sns/jscode2session?appid=%s&secret=%s&js_code=%s&grant_type=authorization_code", appID, secret, code))
	if err != nil {
		return "", fmt.Errorf("请求微信API失败: %w", err)
	}
	defer resp.Body.Close()
	var wr struct {
		OpenID     string `json:"openid"`
		SessionKey string `json:"session_key"`
		ErrCode    int    `json:"errcode"`
		ErrMsg     string `json:"errmsg"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&wr); err != nil {
		return "", fmt.Errorf("解析微信响应失败: %w", err)
	}
	if wr.ErrCode != 0 {
		return "", fmt.Errorf("微信错误 %d: %s", wr.ErrCode, wr.ErrMsg)
	}
	return wr.OpenID, nil
}

package sqlite

import (
	"database/sql"

	"github.com/kiddyt00/yiguan/internal/store"
	"golang.org/x/crypto/bcrypt"
)

// CreateUser 创建用户，密码 bcrypt 哈希，返回 User（不含密码）
func (s *Store) CreateUser(phone, password, nickname string) (*store.User, error) {
	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return nil, err
	}

	result, err := s.db.Exec(
		"INSERT INTO users (phone, nickname, password) VALUES (?, ?, ?)",
		phone, nickname, string(hash),
	)
	if err != nil {
		return nil, err
	}

	id, _ := result.LastInsertId()
	u, err := s.GetUserByID(id)
	if err != nil {
		return nil, err
	}
	u.Password = ""
	return u, nil
}

// CreateUserByOpenID 微信用户创建（无密码，phone 用 wx: 前缀占位）
func (s *Store) CreateUserByOpenID(openid, nickname, wxAvatar string) (*store.User, error) {
	phone := "wx:" + openid[:min(10, len(openid))]
	result, err := s.db.Exec(
		"INSERT INTO users (phone, openid, nickname, wx_avatar, password) VALUES (?, ?, ?, ?, ?)",
		phone, openid, nickname, wxAvatar, "",
	)
	if err != nil {
		return nil, err
	}

	id, _ := result.LastInsertId()
	// 赠送 3 次免费 quota
	for i := 0; i < 3; i++ {
		s.AddQuota(id, "free")
	}

	u, err := s.GetUserByID(id)
	if err != nil {
		return nil, err
	}
	u.Password = ""
	return u, nil
}

// GetUserByPhone 按手机号查找用户
func (s *Store) GetUserByPhone(phone string) (*store.User, error) {
	u := &store.User{}
	err := s.db.QueryRow(
		"SELECT id, phone, COALESCE(openid,''), nickname, avatar, COALESCE(wx_avatar,''), address, password, role, is_active, created_at FROM users WHERE phone = ?",
		phone,
	).Scan(&u.ID, &u.Phone, &u.OpenID, &u.Nickname, &u.Avatar, &u.WxAvatar, &u.Address, &u.Password, &u.Role, &u.IsActive, &u.CreatedAt)
	if err == sql.ErrNoRows {
		return nil, store.ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	return u, nil
}

// GetUserByOpenID 按微信 OpenID 查找用户
func (s *Store) GetUserByOpenID(openid string) (*store.User, error) {
	u := &store.User{}
	err := s.db.QueryRow(
		"SELECT id, phone, COALESCE(openid,''), nickname, avatar, COALESCE(wx_avatar,''), address, password, role, is_active, created_at FROM users WHERE openid = ?",
		openid,
	).Scan(&u.ID, &u.Phone, &u.OpenID, &u.Nickname, &u.Avatar, &u.WxAvatar, &u.Address, &u.Password, &u.Role, &u.IsActive, &u.CreatedAt)
	if err == sql.ErrNoRows {
		return nil, store.ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	return u, nil
}

// GetUserByID 按 ID 查找用户
func (s *Store) GetUserByID(id int64) (*store.User, error) {
	u := &store.User{}
	err := s.db.QueryRow(
		"SELECT id, phone, COALESCE(openid,''), nickname, avatar, COALESCE(wx_avatar,''), address, password, role, is_active, created_at FROM users WHERE id = ?",
		id,
	).Scan(&u.ID, &u.Phone, &u.OpenID, &u.Nickname, &u.Avatar, &u.WxAvatar, &u.Address, &u.Password, &u.Role, &u.IsActive, &u.CreatedAt)
	if err == sql.ErrNoRows {
		return nil, store.ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	return u, nil
}

// UpdateUserOpenID 绑定微信 openid（在已存在用户上设置）
func (s *Store) UpdateUserOpenID(id int64, openid string) error {
	_, err := s.db.Exec("UPDATE users SET openid = ? WHERE id = ?", openid, id)
	return err
}

// UpdateUser 更新昵称和地址
func (s *Store) UpdateUser(id int64, nickname, address string) error {
	_, err := s.db.Exec(
		"UPDATE users SET nickname = ?, address = ? WHERE id = ?",
		nickname, address, id,
	)
	return err
}

// UpdateUserWechatInfo 更新微信用户的昵称、头像和性别
func (s *Store) UpdateUserWechatInfo(id int64, nickname, wxAvatar string) error {
	_, err := s.db.Exec(
		"UPDATE users SET nickname = ?, wx_avatar = ? WHERE id = ?",
		nickname, wxAvatar, id,
	)
	return err
}

// UpdateUserGender 更新微信用户性别（1=男, 2=女）
func (s *Store) UpdateUserGender(id int64, sex int) error {
	_, err := s.db.Exec("UPDATE users SET wx_sex = ? WHERE id = ?", sex, id)
	return err
}

// SearchUsers 按昵称或手机号搜索用户
func (s *Store) SearchUsers(keyword string, limit, offset int) ([]store.User, error) {
	like := "%" + keyword + "%"
	rows, err := s.db.Query(
		"SELECT id, phone, COALESCE(openid,''), nickname, avatar, COALESCE(wx_avatar,''), address, password, role, is_active, created_at FROM users WHERE nickname LIKE ? OR phone LIKE ? ORDER BY id DESC LIMIT ? OFFSET ?",
		like, like, limit, offset,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var list []store.User
	for rows.Next() {
		var u store.User
		rows.Scan(&u.ID, &u.Phone, &u.OpenID, &u.Nickname, &u.Avatar, &u.WxAvatar, &u.Address, &u.Password, &u.Role, &u.IsActive, &u.CreatedAt)
		u.Password = ""
		list = append(list, u)
	}
	return list, rows.Err()
}

// SearchUsersCount 搜索结果总数
func (s *Store) SearchUsersCount(keyword string) (int64, error) {
	var count int64
	like := "%" + keyword + "%"
	err := s.db.QueryRow("SELECT COUNT(*) FROM users WHERE nickname LIKE ? OR phone LIKE ?", like, like).Scan(&count)
	return count, err
}

func min(a, b int) int {
	if a < b { return a }
	return b
}

