// OrderHandler 微信支付订单处理器
type OrderHandler struct {
	store     store.Store
	mchID     string // 商户号
	apiKey    string // API密钥
	appID     string // 公众号AppID
	notifyURL string // 回调地址
}

// NewOrderHandler 创建订单处理器
func NewOrderHandler(st store.Store, mchID, apiKey, appID, notifyURL string) *OrderHandler {
	return &OrderHandler{
		store:     st,
		mchID:     mchID,
		apiKey:    apiKey,
		appID:     appID,
		notifyURL: notifyURL,
	}
}

// products 商品定义
var products = map[string]*store.OrderProduct{
	"basic_quota_1": {
		ProductID: "basic_quota_1",
		Amount:    100,   // 1 元 = 100 分
		Quota:     1,
	},
	"basic_quota_3": {
		ProductID: "basic_quota_3",
		Amount:    200, // 2 元
		Quota:     3,
	},
	"basic_quota_10": {
		ProductID: "basic_quota_10",
		Amount:    500, // 5 元
		Quota:     10,
	},
}

// createOrderReq 下单请求
type createOrderReq struct {
	ProductID string `json:"product_id"`
}

// CreateOrder 创建订单（POST /api/orders/create）
func (h *OrderHandler) CreateOrder(w http.ResponseWriter, r *http.Request) {
	userID := r.Context().Value(middleware.UserIDKey).(int64)

	var req createOrderReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求格式错误"})
		return
	}

	product, ok := products[req.ProductID]
	if !ok {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "商品不存在"})
		return
	}

	outTradeNo := generateOutTradeNo()

	codeURL, err := h.wechatPayNative(product, outTradeNo)
	if err != nil {
		log.Printf("微信支付下单失败: %v", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "支付下单失败"})
		return
	}

	order, err := h.store.CreateOrder(userID, product, outTradeNo, codeURL)
	if err != nil {
		log.Printf("创建订单失败: %v", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "创建订单失败"})
		return
	}

	writeJSON(w, http.StatusOK, map[string]interface{}{
		"id":           order.ID,
		"amount":       order.Amount,
		"quota":        order.Quota,
		"code_url":     order.CodeURL,
		"out_trade_no": order.OutTradeNo,
	})
}

// GetOrder 获取订单详情（GET /api/orders/{id}）
func (h *OrderHandler) GetOrder(w http.ResponseWriter, r *http.Request) {
	userID := r.Context().Value(middleware.UserIDKey).(int64)

	var id int64
	if _, err := fmt.Sscanf(r.PathValue("id"), "%d", &id); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "参数错误"})
		return
	}

	order, err := h.store.GetOrder(id)
	if err != nil {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "订单不存在"})
		return
	}

	if order.UserID != userID {
		writeJSON(w, http.StatusForbidden, map[string]string{"error": "无权访问"})
		return
	}

	writeJSON(w, http.StatusOK, map[string]interface{}{"order": order})
}

// ListOrders 列出用户订单（GET /api/orders）
func (h *OrderHandler) ListOrders(w http.ResponseWriter, r *http.Request) {
	userID := r.Context().Value(middleware.UserIDKey).(int64)

	limit := 20
	offset := 0

	orders, err := h.store.ListOrders(userID, limit, offset)
	if err != nil {
		log.Printf("查询订单列表失败: %v", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "查询失败"})
		return
	}

	if orders == nil {
		orders = []store.Order{}
	}

	writeJSON(w, http.StatusOK, map[string]interface{}{
		"items": orders,
	})
}

// WechatNotify 微信支付回调通知（POST /api/orders/notify）
func (h *OrderHandler) WechatNotify(w http.ResponseWriter, r *http.Request) {
	body, err := io.ReadAll(r.Body)
	if err != nil {
		writeWechatNotifyResp(w, "FAIL", "读取通知失败")
		return
	}

	params, err := parseWechatXML(body)
	if err != nil {
		writeWechatNotifyResp(w, "FAIL", "解析XML失败")
		return
	}

	// 验签
	sign := params["sign"]
	if sign == "" {
		writeWechatNotifyResp(w, "FAIL", "缺少签名")
		return
	}

	expectedSign := wechatSign(params, h.apiKey)
	if !strings.EqualFold(sign, expectedSign) {
		log.Printf("微信回调签名验证失败: got %s, expected %s", sign, expectedSign)
		writeWechatNotifyResp(w, "FAIL", "签名验证失败")
		return
	}

	// 检查业务结果
	if params["return_code"] != "SUCCESS" || params["result_code"] != "SUCCESS" {
		writeWechatNotifyResp(w, "SUCCESS", "OK")
		return
	}

	outTradeNo := params["out_trade_no"]
	prepayID := params["prepay_id"]

	order, err := h.store.GetOrderByOutTradeNo(outTradeNo)
	if err != nil {
		log.Printf("订单查询失败 out_trade_no=%s: %v", outTradeNo, err)
		writeWechatNotifyResp(w, "SUCCESS", "OK")
		return
	}

	if order.Status == "paid" {
		// 已处理，避免重复
		writeWechatNotifyResp(w, "SUCCESS", "OK")
		return
	}

	if err := h.store.MarkOrderPaid(order.ID, prepayID); err != nil {
		log.Printf("标记订单支付失败 id=%d: %v", order.ID, err)
		writeWechatNotifyResp(w, "FAIL", "更新订单失败")
		return
	}

	// 增加配额
	for i := 0; i < order.Quota; i++ {
		if err := h.store.AddQuota(order.UserID, "purchase"); err != nil {
			log.Printf("添加配额失败 user_id=%d: %v", order.UserID, err)
		}
	}

	writeWechatNotifyResp(w, "SUCCESS", "OK")
}

// wechatPayNative 调用微信支付 Native 下单
func (h *OrderHandler) wechatPayNative(product *store.OrderProduct, outTradeNo string) (string, error) {
	// 未配置微信支付，返回 mock 值用于测试
	if h.mchID == "" {
		return "wechat://pay/test?order=" + outTradeNo, nil
	}

	params := map[string]string{
		"appid":            h.appID,
		"mch_id":           h.mchID,
		"nonce_str":        randStr(16),
		"body":             "易观-占卜次数",
		"out_trade_no":     outTradeNo,
		"total_fee":        fmt.Sprintf("%d", product.Amount),
		"spbill_create_ip": "127.0.0.1",
		"notify_url":       h.notifyURL,
		"trade_type":       "NATIVE",
	}

	sign := wechatSign(params, h.apiKey)
	params["sign"] = sign

	xmlBody := buildWechatXML(params)
	log.Printf("微信支付下单请求: %s", xmlBody)

	resp, err := http.Post("https://api.mch.weixin.qq.com/pay/unifiedorder", "application/xml", bytes.NewReader([]byte(xmlBody)))
	if err != nil {
		return "", fmt.Errorf("请求微信支付失败: %w", err)
	}
	defer resp.Body.Close()

	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", fmt.Errorf("读取微信支付响应失败: %w", err)
	}

	log.Printf("微信支付下单响应: %s", string(respBody))

	respParams, err := parseWechatXML(respBody)
	if err != nil {
		return "", fmt.Errorf("解析微信支付响应失败: %w", err)
	}

	if respParams["return_code"] != "SUCCESS" || respParams["result_code"] != "SUCCESS" {
		return "", fmt.Errorf("微信支付下单失败: return_code=%s, result_code=%s, err_code=%s, err_msg=%s",
			respParams["return_code"], respParams["result_code"],
			respParams["err_code"], respParams["err_code_des"])
	}

	return respParams["code_url"], nil
}

// generateOutTradeNo 生成商户订单号
func generateOutTradeNo() string {
	return "YG" + time.Now().Format("20060102150405") + randStr(4)
}

// randStr 生成随机字符串
func randStr(n int) string {
	const charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
	b := make([]byte, n)
	for i := range b {
		idx, _ := rand.Int(rand.Reader, big.NewInt(int64(len(charset))))
		b[i] = charset[idx.Int64()]
	}
	return string(b)
}

// wechatSign 微信支付签名（MD5）
func wechatSign(params map[string]string, apiKey string) string {
	keys := make([]string, 0, len(params))
	for k := range params {
		if k == "sign" {
			continue
		}
		keys = append(keys, k)
	}
	sort.Strings(keys)

	var buf strings.Builder
	for i, k := range keys {
		v := params[k]
		if v == "" {
			continue
		}
		if i > 0 {
			buf.WriteByte('&')
		}
		buf.WriteString(k)
		buf.WriteByte('=')
		buf.WriteString(v)
	}
	buf.WriteString("&key=")
	buf.WriteString(apiKey)

	hash := md5.Sum([]byte(buf.String()))
	return strings.ToUpper(hex.EncodeToString(hash[:]))
}

// buildWechatXML 构建微信支付请求 XML
func buildWechatXML(params map[string]string) string {
	var buf strings.Builder
	buf.WriteString("<xml>")
	// 确保 key 排序输出
	keys := make([]string, 0, len(params))
	for k := range params {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		buf.WriteString(fmt.Sprintf("<%s><![CDATA[%s]]></%s>", k, params[k], k))
	}
	buf.WriteString("</xml>")
	return buf.String()
}

// parseWechatXML 解析微信支付响应 XML
func parseWechatXML(data []byte) (map[string]string, error) {
	params := make(map[string]string)

	decoder := xmlNewDecoder(data)
	for {
		token, err := decoder.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}

		switch se := token.(type) {
		case xmlStartElement:
			if se.Name.Local == "xml" {
				continue
			}
			// 读取元素内容
			var content string
			for {
				t, err := decoder.Token()
				if err != nil {
					return nil, err
				}
				switch ct := t.(type) {
				case xmlCharData:
					content += string(ct)
				case xmlEndElement:
					if ct.Name.Local == se.Name.Local {
						params[se.Name.Local] = strings.TrimSpace(content)
						goto nextField
					}
					// nested elements - skip (WeChat uses flat XML)
					return nil, fmt.Errorf("unexpected nested element: %s", ct.Name.Local)
				}
			}
		nextField:
		}
	}

	return params, nil
}

// XML token types for WeChat XML parsing (no encoding/xml import needed)
type xmlStartElement struct {
	Name xmlName
}

type xmlEndElement struct {
	Name xmlName
}

type xmlCharData string

type xmlName struct {
	Local string
}

// xmlDecoder wraps a byte slice for token-based XML parsing
type xmlDecoder struct {
	data []byte
	pos  int
}

func xmlNewDecoder(data []byte) *xmlDecoder {
	return &xmlDecoder{data: data, pos: 0}
}

func (d *xmlDecoder) Token() (interface{}, error) {
	// Skip whitespace
	for d.pos < len(d.data) {
		c := d.data[d.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			d.pos++
			continue
		}
		break
	}

	if d.pos >= len(d.data) {
		return nil, io.EOF
	}

	if d.data[d.pos] == '<' {
		d.pos++ // skip '<'
		if d.pos >= len(d.data) {
			return nil, io.ErrUnexpectedEOF
		}

		if d.data[d.pos] == '/' {
			// End element
			d.pos++ // skip '/'
			name := readXMLName(d)
			if d.pos < len(d.data) && d.data[d.pos] == '>' {
				d.pos++
			}
			return xmlEndElement{Name: xmlName{Local: name}}, nil
		}

		if d.data[d.pos] == '?' {
			// Processing instruction - skip
			d.pos++
			for d.pos < len(d.data) {
				if d.data[d.pos] == '?' && d.pos+1 < len(d.data) && d.data[d.pos+1] == '>' {
					d.pos += 2
					break
				}
				d.pos++
			}
			return d.Token()
		}

		if d.data[d.pos] == '!' {
			// CDATA or comment
			if d.pos+7 < len(d.data) && string(d.data[d.pos:d.pos+7]) == "![CDATA" {
				for d.pos < len(d.data) {
					if d.data[d.pos] == ']' && d.pos+2 < len(d.data) && d.data[d.pos+1] == ']' && d.data[d.pos+2] == '>' {
						d.pos += 3
						break
					}
					d.pos++
				}
				return d.Token()
			}
			// Comment
			for d.pos < len(d.data) {
				if d.data[d.pos] == '>' {
					d.pos++
					break
				}
				d.pos++
			}
			return d.Token()
		}

		// Start element
		name := readXMLName(d)
		// Skip attributes if any
		for d.pos < len(d.data) {
			if d.data[d.pos] == '>' {
				d.pos++
				break
			}
			if d.data[d.pos] == '/' && d.pos+1 < len(d.data) && d.data[d.pos+1] == '>' {
				d.pos += 2
				// Self-closing, return as start+end
				return xmlStartElement{Name: xmlName{Local: name}}, nil
			}
			d.pos++
		}
		return xmlStartElement{Name: xmlName{Local: name}}, nil
	}

	// Character data
	start := d.pos
	for d.pos < len(d.data) && d.data[d.pos] != '<' {
		d.pos++
	}
	return xmlCharData(string(d.data[start:d.pos])), nil
}

func readXMLName(d *xmlDecoder) string {
	start := d.pos
	for d.pos < len(d.data) {
		c := d.data[d.pos]
		if c == '>' || c == '/' || c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '?' {
			break
		}
		d.pos++
	}
	return string(d.data[start:d.pos])
}

// writeWechatNotifyResp 写入微信回调通知响应
func writeWechatNotifyResp(w http.ResponseWriter, returnCode, returnMsg string) {
	w.Header().Set("Content-Type", "application/xml")
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(fmt.Sprintf(
		"<xml><return_code><![CDATA[%s]]></return_code><return_msg><![CDATA[%s]]></return_msg></xml>",
		returnCode, returnMsg,
	)))
}

